parameters.jsCode:
const raggResponse = $node['RAG - Ingest with Semantic Chunking'].json;
const summaryResponse = $node['Generate Summary (Optional)'].json;
const transcript = $node['STT - Whisper Transcription'].json;

return [{
  json: {
    success: true,
    transcript: transcript.text,
    summary: summaryResponse?.message?.content || null,
    rag_result: {
      chunks_stored: raggResponse.chunks_stored || 0,
      chunk_ids: raggResponse.ids || []
    },
    timestamp: new Date().toISOString()
  }
}];
